"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[802],{3710:function(e,t,a){a.d(t,{default:function(){return r}});var i=a(7437),o=a(8819),s=a(5183),n=a(4508);function r(e){let{children:t,className:a,delay:r=0,direction:d="up",once:l=!0}=e,{ref:c,inView:h}=(0,o.YD)({triggerOnce:l,threshold:.1});return(0,i.jsx)(s.E.div,{ref:c,className:(0,n.cn)(a),variants:{hidden:{opacity:0,y:"up"===d?28:0,x:"left"===d?-28:"right"===d?28:0},visible:{opacity:1,y:0,x:0}},initial:"hidden",animate:h?"visible":"hidden",transition:{duration:.7,delay:r,ease:[.16,1,.3,1]},children:t})}},866:function(e,t,a){a.d(t,{Bz:function(){return i}});let i=[{id:"jack-lopez",name:"Jack Lopez",role:"Creative Director",shortRole:"Creative Direction",bio:"Jack shapes the visual language of every project — building systems that feel intentional and alive.",longBio:["Jack Lopez is the creative mind behind TOAKCO's visual identity work. He approaches every brand as a living system — one that needs to hold up across mediums, scale with the business, and still feel like something the client would have chosen for themselves.","His process is rooted in observation. He listens for what's not being said, pulls references from places most designers wouldn't look, and builds direction from there. The result is work that doesn't feel designed so much as discovered.","Jack leads creative direction across brand identity, campaign work, and the studio's own visual language."],image:"/images/team/jack-lopez.jpg",imageAlt:"Jack Lopez, Creative Director at TOAKCO",skills:["Brand Identity","Creative Direction","Visual Systems","Campaign Design"],quote:"Good design is a conversation between the work and the person who'll live with it.",projects:[{slug:"verdant-provisions",title:"Verdant Provisions",category:"Brand Identity",description:"Full brand system for an urban farm-to-table grocer — mark, type hierarchy, packaging, and environmental signage.",hoverImage:"/images/team/jack-lopez.jpg",year:"2025",tags:["Branding","Packaging","Signage"],body:["Verdant Provisions needed a brand that could live on a paper bag and a storefront awning with equal conviction. The existing visual language was scattered — too many typefaces, no consistent mark, packaging that looked borrowed.","The solution centered on a single anchoring mark: a stylized leaf form built from geometric precision, warm enough to feel handmade. The primary palette leaned into deep forest greens and raw cream, grounded by a secondary warm amber used sparingly for accent.","Type system: a high-contrast serif for display, a humanist sans for body and packaging copy. All guidelines were documented for internal use across three locations and a rotating roster of vendors."]},{slug:"atlas-campaign",title:"Atlas Campaign",category:"Campaign Design",description:"Launch campaign for a travel gear brand. Visual language, print collateral, and digital ad creative across three product lines.",hoverImage:"/images/team/jack-lopez.jpg",year:"2025",tags:["Campaign","Print","Digital Ads"],body:["Atlas came to us mid-product launch — three separate lines, no unified campaign voice, a deadline in six weeks. The brief was straightforward: make the gear look like it belongs on the kind of trip people actually want to take.","The visual system drew from topographic cartography — contour lines, grid overlays, and a deliberately desaturated photography treatment that made every environment feel remote. Headlines used geography as metaphor: elevation, bearing, terrain.","Deliverables spanned full-page print, OOH, paid social in seven formats, and in-store POS across 40 retail partners. Everything built in a shared component library that the client's internal team could extend after handoff."]},{slug:"form-and-field",title:"Form & Field",category:"Visual System",description:"Design system for a mid-size architecture firm — grids, editorial templates, and client-facing document standards.",hoverImage:"/images/team/jack-lopez.jpg",year:"2024",tags:["Design System","Editorial","Print"],body:["Form & Field is a 22-person architecture studio that had grown faster than its internal systems could keep up with. Proposals looked different depending on who assembled them. Presentations had three competing type styles. Client reports had no consistent hierarchy.","The engagement started with an audit — cataloguing every document format, every template, every place where the brand was being interpreted rather than applied. Forty-one document types across six departments.","The resulting system reduced that to twelve base templates, two type scales, a rigorous grid, and a single shared asset library. Visual standards documentation was written directly for the studio's non-designer staff — the people who would actually maintain it."]}]},{id:"max-sims",name:"Max Sims",role:"Motion & Video",shortRole:"Motion + Video",bio:"Max finds the moment inside footage and builds it into something that holds attention.",longBio:["Max Sims came up through filmmaking and found his way to commercial work by learning that the same principles apply everywhere: story first, craft second, tools last.","He handles everything in-house — shoot planning, directing, editing, color, and sound. That full ownership means the final cut is never a compromise between what was intended and what made it through post.","His recent focus has been short-form work that hits within the first two seconds and stays with you after the loop ends."],image:"/images/team/max-sims.jpg",imageAlt:"Max Sims, Motion & Video at TOAKCO",skills:["Video Production","Motion Design","Color Grading","Short-Form Content"],quote:"Every piece of footage has the story already in it. You just have to find the right cut.",projects:[{slug:"coastal-drift",title:"Coastal Drift",category:"Brand Film",description:"Two-minute brand film for a surf lifestyle label — shot over four days on the Oregon coast. Direction, DP, color, and final cut.",hoverImage:"/images/team/max-sims.jpg",year:"2025",tags:["Film","Direction","Color"],body:["The brief was a two-minute brand film. The reality was four days on the Oregon coast in October, shooting in weather that decided not to cooperate on day two.","That turned out to be the film. We abandoned the shot list after the first morning and started following the light — grey, diffuse, completely uncooperative for product work and perfect for everything else. The footage we came back with had a texture the client hadn't expected and couldn't have asked for.","Post ran two weeks: offline cut, color grade in DaVinci, sound mix with field recordings from the coast. The final cut landed 600K organic views in the first month. It now runs as a loop in the brand's flagship store."]},{slug:"fifteen-seconds",title:"Fifteen Seconds",category:"Short-Form Series",description:"Six-part Reels series for a specialty coffee brand. Concept to delivery in three days per episode, 400K+ combined views.",hoverImage:"/images/team/max-sims.jpg",year:"2025",tags:["Reels","Short-Form","Series"],body:["The client had tried short-form video twice before and abandoned it — the turnaround felt too slow to keep pace with the feed, and the content felt like it was chasing a trend that had already moved.","We built a production format that could move at the speed of the platform. Each episode: one visual concept, one hook, one product moment. Fifteen-second runtime, no narration, minimal text. Shot in a single afternoon, edited overnight, posted the next morning.","Six episodes over six weeks. 400K+ combined views, 3.2% average engagement rate (industry benchmark: 1.1%). The series became a repeatable format the brand could run internally after the engagement ended."]},{slug:"motion-system",title:"Motion System",category:"Motion Design",description:"Animated brand identity package for a fintech startup — logo reveals, transitions, and social templates.",hoverImage:"/images/team/max-sims.jpg",year:"2024",tags:["Motion","Identity","After Effects"],body:["A static brand identity is only part of the picture now. When Meridian came to us with a new visual identity already in place, they needed the motion layer — how the logo enters, how the brand moves between states, what the UI feels like in motion.","The motion system started with a single principle: nothing snaps. Every transition has a physical quality — weight, inertia, ease-out. The logo reveal was built around a single arc motion that echoes the brand's mark.","Deliverables: logo reveal in three durations (3s, 6s, 15s), transition toolkit in After Effects, social template suite in 6 formats, and a motion guidelines document that gave their internal team enough to extend the system independently."]}]},{id:"rory-moon",name:"Rory Moon",role:"Web & Digital",shortRole:"Web + Digital",bio:"Rory builds websites that work as hard as they look — fast, intentional, and built to last.",longBio:["Rory Moon bridges design and engineering. She designs with code in mind and builds with aesthetics as a first-class concern — not an afterthought.","She leads web work at TOAKCO, from early Framer prototypes through production. Her sites load fast, scroll smooth, and handle the edge cases that most builds ignore until launch.","Outside of client work, Rory experiments with generative layouts, scroll-driven interactions, and the ongoing question of how much a website can feel like a place."],image:"/images/team/rory-moon.jpg",imageAlt:"Rory Moon, Web & Digital at TOAKCO",skills:["Web Design","Framer","UI/UX","Front-End Development"],quote:"A great website doesn't announce itself. It just gets out of the way and lets the work speak.",projects:[{slug:"hollow-studio",title:"Hollow Studio",category:"Web Design",description:"Portfolio site for an industrial design studio. Scroll-driven reveals, custom cursor, and a full-bleed project archive.",hoverImage:"/images/team/rory-moon.jpg",year:"2025",tags:["Web","Framer","Animation"],body:["Hollow is a six-person industrial design studio whose previous site hadn't been touched in three years. The work had evolved; the site hadn't. Projects that represented real craft were buried in a grid that could have belonged to anyone.","The new site was built around one decision: every project gets the full screen. No grids, no thumbnails — you scroll into each piece. The project archive is a single continuous page with smooth transitions between works, filtered by discipline.","Custom cursor, scroll-velocity-based animations, and a dark/light mode that responds to the project being viewed. Built in Framer. Performance: 98/100 Lighthouse score, sub-2-second LCP."]},{slug:"meridian-app",title:"Meridian App",category:"UI/UX",description:"End-to-end UI design for a B2B logistics dashboard — 40-screen Figma prototype, component library, and developer handoff.",hoverImage:"/images/team/rory-moon.jpg",year:"2024",tags:["UI/UX","Figma","Design System"],body:["Meridian is a logistics platform that had outgrown its MVP UI. The original interface was built by engineers for engineers — functional, but requiring too much context to use efficiently at scale.","The redesign started with a two-week research phase: five user interviews, a full heuristic audit, and a card-sorting exercise to validate navigation architecture. The core problem: too many layers, too little surface area for the information density the job required.","The resulting system — 40 screens, a 200-component Figma library, and a 48-page handoff document — reduced the average task completion time by 34% in usability testing. The component library was built with developer handoff annotations on every token, state, and responsive behavior."]},{slug:"generative-type",title:"Generative Type",category:"Experiment",description:"Personal project exploring CSS Houdini and variable fonts — typography that responds to scroll position and cursor proximity.",hoverImage:"/images/team/rory-moon.jpg",year:"2024",tags:["Experiment","CSS","Typography"],body:["This started as a question: how much can type behave before it stops being readable? The project used CSS Houdini's Paint Worklet API to create typography that responds to the environment — scroll position shifts weight axis, cursor proximity shifts width.","The technical constraint became the creative constraint. Houdini is still behind a flag in some browsers, which meant the entire thing had to degrade gracefully to static type. That forced a cleaner base design than a JavaScript-first approach would have produced.",'The experiment runs in Chrome and Edge with Houdini enabled. The source is public. It became a reference point for a conversation about what "responsive" means when applied to individual letterforms rather than layout.']}]},{id:"samuel-salamanca",name:"Samuel Salamanca",role:"Strategy & Content",shortRole:"Strategy + Content",bio:"Samuel connects creative vision to audience reality — building content that reaches and resonates.",longBio:["Samuel Salamanca approaches content as infrastructure. A good post isn't just good — it's positioned right, timed right, and part of something bigger.","He leads strategy and content at TOAKCO, which means he's thinking about campaign architecture, platform behavior, and what the audience actually wants to see before any asset gets made.","His background in social media management gives him an operational edge: he doesn't just plan campaigns, he runs them, adapts them in real-time, and knows how to read what's working."],image:"/images/team/samuel-salamanca.jpg",imageAlt:"Samuel Salamanca, Strategy & Content at TOAKCO",skills:["Content Strategy","Social Media","Campaign Planning","Copywriting"],quote:"Strategy without creativity is just a calendar. Creativity without strategy is just noise.",projects:[{slug:"root-and-rise",title:"Root & Rise",category:"Content Strategy",description:"Six-month content strategy for a wellness brand. Editorial calendar, platform playbooks, and voice guidelines for a team of four.",hoverImage:"/images/team/samuel-salamanca.jpg",year:"2025",tags:["Strategy","Editorial","Voice"],body:["Root & Rise had content — a lot of it — but no architecture. Posts went out when inspiration hit. Campaigns were assembled the week before launch. The audience was there; the content wasn't giving them a reason to stay.","The strategy engagement started by mapping what already existed: 18 months of posts across three platforms, performance data, audience comments, DMs. The pattern that emerged was clear — their most engaged content was the most specific. The least engaged was the broadest.","The resulting system: six content pillars, three platform-specific playbooks, a voice guide built from their own best-performing copy, and a 90-day editorial calendar. Six months in: 340% increase in saves, 2.1x follower growth, first campaign that sold out product in 48 hours."]},{slug:"launch-sequence",title:"Launch Sequence",category:"Campaign",description:"Product launch campaign for a boutique skincare line — content calendar, copy, and real-time performance management across Instagram and TikTok.",hoverImage:"/images/team/samuel-salamanca.jpg",year:"2025",tags:["Campaign","Social","Launch"],body:["The client had a 90-day runway to launch three new SKUs with no paid budget — organic only, two platforms, a team of two. The challenge wasn't creativity; it was sequencing. What goes out when, and in what order, to build genuine purchase intent rather than just awareness.","The campaign architecture ran in four phases: tease (days 1-21), education (days 22-45), social proof (days 46-70), and open cart (days 71-90). Each phase had its own content types, posting frequency, and engagement strategy.","Results: 18K new followers across platforms in 90 days. Launch week sold through the initial inventory run in 31 hours. The post-launch debrief framework we built became the client's standard operating procedure for every product drop since."]},{slug:"the-long-game",title:"The Long Game",category:"Writing",description:"Long-form essay series on brand storytelling for small businesses. Published independently, 12K subscribers.",hoverImage:"/images/team/samuel-salamanca.jpg",year:"2024",tags:["Writing","Newsletter","Strategy"],body:["The Long Game started as a place to think out loud about something that kept coming up in client work: most small businesses understand they need content, but almost none of them understand what it's actually for.","The newsletter runs monthly. Each issue takes one strategic concept — positioning, audience specificity, platform selection, the difference between building an audience and building a customer base — and examines it through the lens of a real business decision.","Twelve issues published over fourteen months. 12,400 subscribers, 54% average open rate (industry average: 22%). Three issues were cited in brand strategy courses at two universities. No paid promotion — growth entirely through reader referrals and one guest post."]}]},{id:"joey-markley",name:"Joey Markley",role:"Founder & Operations",shortRole:"Founder",bio:"Joey built TOAKCO on the belief that small teams with clear values do the best creative work.",longBio:["Joey Markley started TOAKCO because he kept seeing the same problem: great clients stuck with generic creative, and talented people doing work that didn't feel like theirs.","He built the studio around a different model — a small, integrated team with full ownership of each project, from strategy through execution. No handoffs to contractors. No diluted vision.","Outside the studio, Joey is finishing a design research capstone at NC State — Adaptive Clarity, an AI-powered ambient companion built specifically for ADHD minds. It's the same philosophy applied to a different problem: thoughtful systems over loud ones.","He runs operations, client relationships, and the systems that keep everything moving. He's also the person most likely to be stress-testing a new workflow at midnight because it's almost working and he wants to see it work."],image:"/images/team/joey-markley.jpg",imageAlt:"Joey Markley, Founder of TOAKCO",skills:["Studio Operations","Client Relations","AI Integration","Brand Strategy"],quote:"The studio is only as good as the trust between the people making the work.",tools:[{slug:"adobe-creative-cloud",name:"Adobe Creative Cloud",use:"Brand design, print assets, and campaign production",hoverImage:"/assets/capstone/studio-forest.png",body:["Adobe CC is the production backbone for all TOAKCO brand and print work. Illustrator for vector identity systems, Photoshop for image treatment and retouching, InDesign for editorial layouts and client-facing documents.","For campaign work, the workflow typically runs: concept in Figma → production in Illustrator/Photoshop → final delivery as PDF/X-1a for print or optimized assets for digital. Video and motion work routes through Premiere and After Effects when the project calls for it.","The full suite stays current on every machine in the studio. It's not the most exciting tool to talk about, but it's the one everything else depends on."]},{slug:"claude-code",name:"Claude Code",use:"AI-native development and studio workflow automation",hoverImage:"/assets/capstone/studio-forest.png",body:["Claude Code runs as the primary development environment for the TOAKCO site and all studio automation work. The agentic loop — where Claude can read, write, and execute code directly in the terminal — changed how the studio approaches both web builds and internal tooling.","The workflow: Claude Code handles architecture decisions, writes and refactors components, runs the build, interprets errors, and iterates. A full page build that used to take two days can move in an afternoon. The quality floor is higher because every decision is reasoned, not just typed.","Beyond the site, Claude Code powers Paco Bot, the Higgsfield pipeline, the video compression scripts, and the intake workflows. The studio runs meaningfully faster because of it."]},{slug:"higgsfield",name:"Higgsfield",use:"AI image and video generation for campaigns and research",hoverImage:"/assets/capstone/device-perspective.png",body:["Higgsfield is the studio's primary tool for AI-generated visual content. The image generation pipeline is integrated directly into the TOAKCO site build — prompts are iterated, outputs are reviewed, and approved assets are compressed and served through the Next.js image pipeline.","For campaigns, Higgsfield generates concept imagery that would be prohibitively expensive to shoot: product environments, atmospheric photography, abstract brand visuals. The quality at the right prompt is genuinely useful for client mockups and spec work.","The most significant application was the Adaptive Clarity capstone — all five technical renders (orthographic, perspective, exploded, skeleton, schematic) were generated through Higgsfield from detailed product descriptions. It compressed a weeks-long visualization process into a single session."],gallery:[{slug:"device-renders",title:"Adaptive Clarity Device Renders",description:"All five technical renders generated via Higgsfield for the Adaptive Clarity DS 483 capstone — orthographic, perspective, exploded, skeleton, and schematic views.",coverImage:"/assets/capstone/device-perspective.png",images:["/assets/capstone/device-orthographic.png","/assets/capstone/device-perspective.png","/assets/capstone/device-exploded.png","/assets/capstone/device-skeleton.png","/assets/capstone/device-schematic.png"]}]},{slug:"notion",name:"Notion",use:"Knowledge management, client documentation, and briefs",hoverImage:"/assets/capstone/studio-forest.png",body:["Notion is where everything in the studio lives that isn't code. Client briefs, project timelines, brand guidelines, meeting notes, research archives, and the intake process that feeds Paco Bot.","The studio database structure: a master Projects table linked to Clients, Tasks, Deliverables, and Assets. Every client gets their own workspace with a standardized structure — brief, brand guidelines, asset library, feedback log, delivery checklist.","The intake workflow is particularly load-bearing: new project requests come in via Discord, Paco Bot processes them and creates a Notion page with the structured brief, which then feeds the project timeline. No brief lives in email or Slack."]},{slug:"figma",name:"Figma",use:"UI/UX design, design system components, and prototypes",hoverImage:"/assets/capstone/studio-forest.png",body:["Figma handles all UI/UX work before anything touches code. The TOAKCO design system lives here — every component, color token, type style, and spacing unit. The Figma file and the codebase stay in sync through a Code Connect mapping that Claude Code maintains.","For client web projects, the flow is always design-in-Figma first: wireframes → high-fidelity → interactive prototype → developer handoff with annotated specs. Clients review and approve in Figma before any code is written.","The component library mirrors the Tailwind token system closely enough that translating from Figma to code is mechanical rather than interpretive. That's the goal — no ambiguity between what was designed and what gets built."]},{slug:"gsap-nextjs",name:"GSAP + Next.js",use:"Scroll-driven web animation and site architecture",hoverImage:"/assets/capstone/studio-forest.png",body:["The TOAKCO site is built on Next.js 14 App Router — static generation where possible, server components for metadata and routing, client components only where interactivity requires it. The architecture keeps the bundle small and the pages fast.","GSAP handles all scroll-driven animation: text reveals (chars/words/lines via ScrollTrigger), pinned sections, multi-step timelines, and the Higgsfield video overlay system. Framer Motion handles component-level transitions and entrance animations. The split is intentional — each library does what it does best.","The GSAP component library lives at `components/gsap/`: GSAPTextReveal, GSAPScrollSection, GSAPLogoReveal, GSAPHiggsOverlay. New animations always start from these primitives rather than from scratch."]},{slug:"python",name:"Python",use:"Video compression, transcription pipelines, and automation scripts",hoverImage:"/assets/capstone/device-schematic.png",body:["Python handles the media processing layer of the studio — everything that involves files moving, transforming, and being optimized at scale. The core script is higgsfield-compress.py: takes 4K outputs from Higgsfield, runs FFmpeg to produce 1080p MP4, 1080p WebM, 720p fallback, and a poster frame, then places them in the right directory for the Next.js asset pipeline.","The transcription pipeline takes raw interview and client call recordings, runs them through Whisper locally, and produces structured transcripts with speaker labels. These feed directly into Paco Bot's brief-drafting workflow.","The writing voice system (mac_writing_assistant.py) captures Joey's academic and professional voice from existing writing, then applies it to new drafts on request. It runs locally, stores nothing externally, and produces output that passes close reading."]}],projects:[{slug:"adaptive-clarity",title:"Adaptive Clarity",category:"Product + Research",description:"An AI-powered ambient companion for ADHD minds. Dual-component system: mobile app and physical desk device. DS 483 capstone, NC State.",hoverImage:"/assets/capstone/device-orthographic.png",year:"2026",tags:["Product Design","Research","AI"],body:["Adaptive Clarity started from a specific frustration: every productivity tool designed for ADHD minds was built around the same broken assumptions as every other productivity tool. Streaks, notifications, gamification — all the mechanics that feel motivating to neurotypical product designers feel punishing to people with ADHD.","The research phase pulled 40+ interviews, literature on ADHD productivity patterns, and a competitive audit of 18 existing tools. The pattern was clear: the apps that worked were the ones that stayed out of the way. Ambient, peripheral, zero friction.","The dual-component system — a voice-first mobile app paired with a physical desk companion — came from that research. The app handles session management through spoken interaction. The device communicates state through ambient LED changes visible in peripheral vision. No sound. No vibration. No pop-ups. The physical presence of the device creates an environmental cue that a phone notification never can."],gallery:[{slug:"orthographic-renders",title:"Orthographic Production Views",description:"1/7 scale orthographic renders showing front, side, and top views for production documentation.",coverImage:"/assets/capstone/device-orthographic.png",images:["/assets/capstone/device-orthographic.png","/assets/capstone/device-perspective.png"]},{slug:"technical-overview",title:"Technical Exploded View",description:"Four-panel technical overview showing component relationships, assembly sequence, and internal layout.",coverImage:"/assets/capstone/device-exploded.png",images:["/assets/capstone/device-exploded.png","/assets/capstone/device-skeleton.png"]},{slug:"engineering-drawings",title:"Engineering Drawings",description:"Top shell assembly engineering drawings with dimensional callouts and material specifications.",coverImage:"/assets/capstone/device-schematic.png",images:["/assets/capstone/device-schematic.png"]}]},{slug:"paco-bot",title:"Paco Bot",category:"Automation",description:"Discord AI assistant for the TOAKCO studio. Claude API integration, real-time voice, image and file processing, and Batch API.",hoverImage:"/assets/capstone/studio-forest.png",year:"2025",tags:["Automation","Claude API","Discord"],body:["Paco started as a simple Discord bot for routing questions to Claude. It grew into the operating layer of the studio — the thing that handles intake, transcription, brief drafts, image generation requests, and async task management across the team.","The core architecture: a Node.js bot connected to the Claude API, with tool-use enabled for web search, image processing, file handling, and Higgsfield generation. Voice integration uses Whisper for transcription and ElevenLabs for response audio. Three voice profiles for different contexts.","The Batch API integration was the unlock — it let Paco process large research requests and multi-step content jobs asynchronously, with results delivered back to the right Discord channel when complete. The studio now runs a meaningful percentage of its research and first-draft work through Paco."]},{slug:"toakco-com",title:"TOAKCO.com",category:"Web",description:"Studio site built with Next.js 14, GSAP scroll animations, Higgsfield video pipeline, and a custom design system.",hoverImage:"/assets/capstone/studio-forest.png",year:"2025",tags:["Next.js","GSAP","Design System"],body:["The TOAKCO site needed to do something most studio sites don't: demonstrate the work rather than just describe it. The stack — Next.js 14 App Router, GSAP with ScrollTrigger, Framer Motion, Tailwind — was chosen specifically to let the site be the case study.","The design system was built ground-up: a custom color scale derived from the brand palette, two font pairings (Cormorant Garamond display + Inter body), a component library that covers every UI pattern the site uses, and a strict token architecture that makes the whole thing maintainable.","The Higgsfield pipeline was integrated directly into the build process — generated images and videos are compressed, optimized, and served through Next.js Image for core web vitals compliance. GSAP handles all scroll-driven animation; Framer handles component-level transitions. The split keeps each library doing what it's best at."],gallery:[{slug:"studio-setup",title:"Studio Environment",description:"Photography studio setup in a forest environment — used as the hero background for the Joey Markley personal page.",coverImage:"/assets/capstone/studio-forest.png",images:["/assets/capstone/studio-forest.png"]}]}],capstoneCTA:{label:"Adaptive Clarity",href:"/capstone",description:"An AI-powered focus companion for ADHD minds — ambient light, no notifications, voice-first interaction."}}]},4508:function(e,t,a){a.d(t,{cn:function(){return s}});var i=a(1994),o=a(3335);function s(){for(var e=arguments.length,t=Array(e),a=0;a<e;a++)t[a]=arguments[a];return(0,o.m6)((0,i.W)(t))}}}]);